const management=[['quan-ly','Quỹ căn',Building2],['khach-hang','Khách hàng',Users],['giao-dich','Giao dịch',BriefcaseBusiness],['thu-vien','Thư viện',FileText],['cau-hinh','Cấu hình',SettingsIcon]] as const;
