{section==='du-an'&&route[1]&&(chosenProject?<ProjectWorkspace key={chosenProject.id} canManage={mayEdit} projects={projects} project={chosenProject} units={units.filter(u=>u.projectId===chosenProject.id)} assets={state.files.filter(f=>f.projectId===chosenProject.id)} pins={state.records.filter(r=>r.kind==='pin'&&r.data?.projectId===chosenProject.id).map(r=>r.data)} onReload={reload} statusOf={statusOf} onSelect={setSelected} onFavorite={favorite} favorites={favorites} onCompare={toggleCompare} compare={compare} exportUnits={exportUnits} sourceStatus={greenStatus} initialTab={resolveProjectTab(route[2],initialProjectTab)} initialMatrix={initialProjectView==='floors'}/>:<section className="container section-space"><EmptyBox title="Không tìm thấy dự án" description="Chọn một dự án trong danh mục để tiếp tục."/><Link href="/du-an" className="button dark">Danh sách dự án</Link></section>)}
{section==='yeu-thich'&&<SzBanner title="Yêu thích" aside="Các căn và dự án bạn đã lưu để xem lại và so sánh."/>}
{section==='yeu-thich'&&<section className="container section-space"><div className="section-heading"><div><span className="eyebrow brown">BỘ SƯU TẬP CỦA BẠN</span><h1>Danh sách yêu thích</h1></div><Heart size={30}/></div><h2>Quỹ căn đã lưu</h2><div className="unit-grid">{units.filter(u=>favorites.has(u.id)).map(u=><UnitCard key={u.id} u={u} p={projectOf(u)} status={statusOf(u)} projectCount={unitCounts.get(u.projectId)||0} favorited={favorites.has(u.id)} compared={compare.includes(u.id)} onFavorite={favorite} onCompare={toggleCompare}/>)}</div>{!units.some(u=>favorites.has(u.id))&&<EmptyBox title="Chưa có căn yêu thích" description="Nhấn trái tim trên các căn bạn quan tâm để lưu vào đây."/>}<h2>Dự án đã lưu</h2><div className="project-grid">{projects.filter(p=>favorites.has(p.id)).map(p=><ProjectCard key={p.id} p={p} unitCount={unitCounts.get(p.id)||0} favorited={favorites.has(p.id)} onFavorite={favorite}/>)}</div></section>}
{!adminMode&&section==='huong-dan'&&<SzBanner title="Hướng dẫn" aside="Cách tra cứu quỹ căn, xem mặt bằng 360°, giữ chỗ và quản lý khách hàng trên Alpha Hub."/>}
