{adminMode&&section==='gioi-thieu'&&<AdminAbout content={aboutContent} projects={projects} busy={busy} onSave={data=>action({action:'save',kind:'about',id:'main',data},'Đã cập nhật trang giới thiệu.')}/>}
{adminMode&&section==='huong-dan'&&<AdminGuides guides={guideContent} busy={busy} onSave={data=>action({action:'save',kind:'guide',id:data.id,data},'Đã cập nhật hướng dẫn.')}/>}
{section==='tong-quan'&&<AdminOverview projects={projects} customers={customers} reservations={state.reservations} files={state.files} savedUnits={state.records.filter(r=>r.kind==='unit').length} notifications={notifications}/>}
{section==='quan-ly-du-an'&&<AdminProjects projects={projects} onCreate={()=>setEditor({kind:'project',data:{id:crypto.randomUUID(),name:'',location:'',region:'',developer:'',category:'low',status:'Đang mở bán',image:'',description:'',hot:false,lat:0,lng:0}})} onEdit={project=>setEditor({kind:'project',data:{...project}})}/>}
{section==='bai-viet'&&<><div className="section-heading"><SearchBox value={query} onChange={setQuery} placeholder="Tìm bài viết..."/><button className="button dark" onClick={()=>setEditor({kind:'article',data:{id:crypto.randomUUID(),title:'',category:'Tin tức',body:'',image:'',date:new Date().toISOString().slice(0,10)}})}><Plus size={17}/>Thêm bài viết</button></div><div className="table-wrap"><Table><TableHeader><TableRow><TableHead>Tiêu đề</TableHead><TableHead>Chuyên mục</TableHead><TableHead>Ngày đăng</TableHead><TableHead>Thao tác</TableHead></TableRow></TableHeader><TableBody>{articles.filter(a=>a.title.toLowerCase().includes(query.toLowerCase())).map(a=><TableRow key={a.id}><TableCell>{a.title}</TableCell><TableCell>{a.category}</TableCell><TableCell>{a.date}</TableCell><TableCell><div className="row"><Link className="button subtle" href={'/tin-tuc/'+encodeURIComponent(a.id)} target="_blank" rel="noreferrer"><Eye size={15}/>Xem tin</Link><button className="button subtle" onClick={()=>setEditor({kind:'article',data:{...a}})}><Pencil size={15}/>Chỉnh sửa</button></div></TableCell></TableRow>)}</TableBody></Table></div></>}
{section==='quan-ly'&&<><div className="stat-grid">{[[Building2,'Quỹ căn',units.length],[House,'Còn hàng',units.filter(u=>statusOf(u)==='Còn hàng').length],[Clock,'Đang giữ chỗ',units.filter(u=>statusOf(u)==='Đang giữ chỗ').length],[Check,'Đã bán',units.filter(u=>statusOf(u)==='Đã bán').length]].map(([Icon,label,value]:any)=><div className="stat-card" key={label}><Icon size={23}/><span>{label}</span><strong>{value}</strong></div>)}</div><div className="section-heading"><SearchBox value={query} onChange={setQuery} placeholder="Tìm mã căn hoặc dự án..."/><div className="row"><button className="button subtle" onClick={()=>{downloadCsv('mau-nhap-quy-can.csv',[{...seedUnits[0],id:'',code:'MA-CAN-MOI'}]);}}><Download size={16}/>Mẫu CSV</button><label className="button subtle"><Upload size={16}/>Nhập CSV<input type="file" accept=".csv,text/csv" className="hidden" onChange={async e=>{const file=e.target.files?.[0];if(!file)return;try{const parsed=parseCsv(await file.text());if(!parsed.length||parsed.length>300)throw Error('Mỗi lần nhập từ 1 đến 300 căn.');const rows=parsed.map((r,i)=>{if(!projects.some(p=>p.id===r.projectId))throw Error(`Dòng ${i+2}: projectId không tồn tại.`);const out:any={...seedUnits[0],...r,id:r.id||crypto.randomUUID()};for(const k of ['area','builtArea','price','beds','floor','x','y']){out[k]=Number(out[k]);if(!Number.isFinite(out[k])||out[k]<0)throw Error(`Dòng ${i+2}: ${k} không hợp lệ.`);}return out as Unit;});setImportRows(rows);}catch(e){toast.error((e as Error).message);}e.target.value='';}}/></label><button className="button dark" onClick={()=>setEditor({kind:'unit',data:{...seedUnits[0],id:crypto.randomUUID(),code:'',projectId:projects[0].id,price:0,note:''}})}><Plus size={17}/>Thêm căn</button></div></div><p className="muted small">Giá và quỹ căn ban đầu là dữ liệu minh họa. Các thay đổi được lưu ở backend và cập nhật bảng hàng ngoài website.</p><UnitTable projectOf={projectOf} statusOf={statusOf} onSelect={setSelected} onEdit={u=>setEditor({kind:'unit',data:{...u}})} manage items={units.filter(u=>(u.code+' '+projectOf(u).name).toLowerCase().includes(query.toLowerCase())).slice((page-1)*50,page*50)}/><div className="admin-page-controls"><button className="button subtle" disabled={page<=1} onClick={()=>setPage(page-1)}>Trang trước</button><span>Trang {page}</span><button className="button subtle" disabled={page*50>=units.filter(u=>(u.code+' '+projectOf(u).name).toLowerCase().includes(query.toLowerCase())).length} onClick={()=>setPage(page+1)}>Trang sau</button></div><div className="section-heading"><h2>Quản lý dự án</h2><button className="button subtle" onClick={()=>setEditor({kind:'project',data:{...projects[0],id:crypto.randomUUID(),name:'',location:'',image:'',description:'',hot:false}})}><Plus size={16}/>Thêm dự án</button></div><div className="table-wrap"><Table><TableHeader><TableRow><TableHead>Dự án</TableHead><TableHead>Khu vực</TableHead><TableHead>Chủ đầu tư</TableHead><TableHead></TableHead></TableRow></TableHeader><TableBody>{projects.map(p=><TableRow key={p.id}><TableCell>{p.name}</TableCell><TableCell>{p.region}</TableCell><TableCell>{p.developer}</TableCell><TableCell><button className="button subtle" onClick={()=>setEditor({kind:'project',data:{...p}})}><Pencil size={15}/>Chỉnh sửa</button></TableCell></TableRow>)}</TableBody></Table></div></>}
